// ── ANTI-PATTERN: Singleton as global state dump ───────────────────────
class AppState {
  static #instance = null;

  constructor() {
    this.user         = null;    // auth concern
    this.cartItems    = [];      // shopping concern
    this.theme        = 'light'; // UI concern
    this.featureFlags = {};      // ops/devops concern
    this.activeModal  = null;    // navigation concern
  }

  static getInstance() {
    if (!AppState.#instance) AppState.#instance = new AppState();
    return AppState.#instance;
  }
}

// Module A: auth
const state = AppState.getInstance();
state.user = { id: 1, name: 'Alice' }; // who set this? when? what else changed?

// Module B: shopping cart
const s2 = AppState.getInstance();
s2.cartItems.push({ sku: 'p1', qty: 2 }); // mutation invisible to any reader

// Test problem: to reset between tests you must hack private field
// AppState['_AppState__instance'] = null; // fragile, engine-dependent
// Any test that forgets this line poisons subsequent tests


// ── REFACTOR: split by concern, inject as dependency ──────────────────
class AuthStore {
  constructor() { this._user = null; }
  login(user)  { this._user = user; }
  logout()     { this._user = null; }
  getUser()    { return this._user; }
}

class CartStore {
  constructor() { this._items = []; }
  add(item)    { this._items = [...this._items, item]; }  // immutable update
  remove(sku)  { this._items = this._items.filter(i => i.sku !== sku); }
  getItems()   { return [...this._items]; }               // defensive copy
}

class ThemeStore {
  constructor(initial = 'light') { this._theme = initial; }
  setTheme(t)  { this._theme = t; }
  getTheme()   { return this._theme; }
}

// Constructed once at the application root and injected downward:
const auth  = new AuthStore();
const cart  = new CartStore();
const theme = new ThemeStore();

auth.login({ id: 1, name: 'Alice' });
cart.add({ sku: 'p1', qty: 2 });
theme.setTheme('dark');

console.log(auth.getUser().name);   // Alice
console.log(cart.getItems());       // [{ sku: 'p1', qty: 2 }]
console.log(theme.getTheme());      // dark

// In tests: pass new AuthStore(), new CartStore() — no teardown needed.
// const authInTest = new AuthStore(); // clean slate, zero ceremony


// ── ANTI-PATTERN: Premature Factory ──────────────────────────────────
class UserFactory {
  static create(data) {
    return new User(data);   // trivial delegation — adds a file for zero benefit
  }
}

// BETTER: just use the constructor until you have 2+ types
class User {
  constructor({ id, name, role = 'viewer' }) {
    this.id   = id;
    this.name = name;
    this.role = role;
  }
}
const u = new User({ id: 42, name: 'Bob' });
console.log(u.role); // viewer


// ── Factory JUSTIFIED: multiple runtime types + complex init ──────────
function createNotifier(channel, config) {
  switch (channel) {
    case 'email': return new EmailNotifier(config);
    case 'sms':   return new SmsNotifier(config);
    case 'push':  return new PushNotifier(config);
    default: throw new Error(`Unknown notification channel: ${channel}`);
  }
}
// Three concrete types, determined at runtime from user/config data.
// Call sites are shielded from construction complexity.
// Swapping implementations for tests is trivial: stub createNotifier.

class EmailNotifier { send(msg) { console.log(`[Email] ${msg}`); } }
class SmsNotifier   { send(msg) { console.log(`[SMS]   ${msg}`); } }
class PushNotifier  { send(msg) { console.log(`[Push]  ${msg}`); } }

const channel = process.env.NOTIFY_CHANNEL || 'sms';
const notifier = createNotifier(channel, {});
notifier.send('Your order shipped!'); // [SMS]   Your order shipped!

// ── ANTI-PATTERN: Observer for sequential pipeline logic ──────────────
const EventEmitter = require('events');
const bus = new EventEmitter();

// Sequential steps wired through events — execution order determined
// by registration order, invisible from any single file
bus.on('pipeline:step1:done', (ctx) => {
  ctx.step1Result = processStep1(ctx.input);
  bus.emit('pipeline:step2:start', ctx);
});
bus.on('pipeline:step2:start', (ctx) => {
  ctx.step2Result = processStep2(ctx.step1Result);
  bus.emit('pipeline:step2:done', ctx);
});
bus.on('pipeline:step2:done', (ctx) => {
  console.log('Done:', ctx.step2Result);
});

// To run the pipeline:
bus.emit('pipeline:step1:done', { input: 'raw data' });
// Problem: where does the pipeline start? Who handles errors in step2?
// What if a third listener registers for 'step2:done'? Invisible side effect.

function processStep1(x) { return x.toUpperCase(); }
function processStep2(x) { return x.split('').reverse().join(''); }


// ── REFACTOR: sequential logic stays sequential ────────────────────────
function runPipeline(input) {
  const step1Result = processStep1(input);      // readable
  const step2Result = processStep2(step1Result); // obvious chain
  return step2Result;
}
console.log(runPipeline('raw data')); // ATAD WAR
// Stack trace, debugger breakpoints, and unit tests all work naturally.


// ── Observer JUSTIFIED: genuine fan-out, unknown subscribers ──────────
const orderEvents = new EventEmitter();

// Order service emits — does NOT know who listens
function placeOrder(order) {
  // ... persist order ...
  orderEvents.emit('order:placed', order);
}

// Three independent systems subscribe — each in their own module:
orderEvents.on('order:placed', (order) => {
  console.log(`[Email] Confirmation sent for order ${order.id}`);
});
orderEvents.on('order:placed', (order) => {
  console.log(`[Inventory] Stock reserved for order ${order.id}`);
});
orderEvents.on('order:placed', (order) => {
  console.log(`[Analytics] Conversion recorded for order ${order.id}`);
});

placeOrder({ id: 'ORD-42', items: ['p1', 'p2'] });
// [Email] Confirmation sent for order ORD-42
// [Inventory] Stock reserved for order ORD-42
// [Analytics] Conversion recorded for order ORD-42
// The order module is isolated. Adding a 4th subscriber requires
// zero changes to the order module — this is Observer's actual value.


// ── ANTI-PATTERN: Needless inheritance hierarchy ───────────────────────
class BaseController {
  handleError(err) { console.error(err); }
}
class AbstractCrudController extends BaseController {
  paginate(items, page, limit) { return items.slice((page-1)*limit, page*limit); }
}
class GenericResourceController extends AbstractCrudController {
  list() { return []; }   // to be overridden
}
class UserController extends GenericResourceController {
  list() {
    const users = [{ id: 1, name: 'Alice' }];
    return this.paginate(users, 1, 10);   // the only real work
  }
}
// Four files to navigate to understand one endpoint.

// ── REFACTOR: flat function + extracted helper when needed ─────────────
function paginate(items, page = 1, limit = 10) {
  return items.slice((page - 1) * limit, page * limit);
}
function listUsers({ page, limit } = {}) {
  const users = [{ id: 1, name: 'Alice' }];
  return paginate(users, page, limit);
}
console.log(listUsers({ page: 1, limit: 10 })); // [{ id: 1, name: 'Alice' }]
// When listOrders appears with the same pagination need, `paginate` is already there.
// The abstraction was extracted at the natural moment — not pre-built for it.
